### hub completion - begin. generated by omelette.js ###
if type compdef &>/dev/null; then
  _hub_completion() {
    compadd -- `hub __complete "${words[@]:1}"`
  }
  compdef _hub_completion hub
elif type complete &>/dev/null; then
  _hub_completion() {
    local cur prev nb_colon
    _get_comp_words_by_ref -n : cur prev
    nb_colon=$(grep -o ":" <<< "$COMP_LINE" | wc -l)

    COMPREPLY=( $(compgen -W '$(hub __complete "${COMP_WORDS[@]:1}")' -- "$cur") )

    __ltrim_colon_completions "$cur"
  }
  complete -F _hub_completion hub
elif type compctl &>/dev/null; then
  _hub_completion () {
    local cword line point si
    read -Ac words
    read -cn cword
    read -l line
    si="$IFS"
    if ! IFS=$'
' reply=($(hub __complete "${words[@]:1}")); then
      local ret=$?
      IFS="$si"
      return $ret
    fi
    IFS="$si"
  }
  compctl -K _hub_completion hub
fi
### hub completion - end ###